func:
// Zone bounds in mm, radar frame: x lateral (+/-), y forward from sensor.
// MEASURED 2026-09-12 from a walk test: downstairs approach, up the stairs,
// exit top, return, and back down. Both approaches funnel through a gate at
// x ~ -660, y ~ 1030-1280, which is what these bounds are built around.
//   xMax 2000  - widest use was +23.5 deg; the track never neared the fan edge
//   xMin -2000 - deliberately excludes the x -2090 leg walking off to the
//                workshop, so leaving does not hold the light on
//   yMax 4000  - turns the light on ~7 s before the gate. Raising it to 5000
//                buys ~2 s more warning but reacts to movement 5 m out
//   yMin 300   - NOT 1000. The closest measured approach was y=1031, so 1000
//                looks safe and tests clean, but anyone passing nearer would
//                fall outside and the light would cut out mid-staircase.
const ZONE = { xMin: -2000, xMax: 2000, yMin: 300, yMax: 4000 };

let d;
try {
    d = JSON.parse(msg.payload);
} catch (e) {
    return null; // malformed payload
}
if (!d || typeof d !== "object") {
    return null; // not an object payload
}
if (d.gone) {
    return null; // disappearance = inactivity; the trigger timeout handles it
}
if (typeof d.x !== "number" || typeof d.y !== "number") {
    return null;
}
if (d.x < ZONE.xMin || d.x > ZONE.xMax || d.y < ZONE.yMin || d.y > ZONE.yMax) {
    return null; // outside the zone
}
return msg; // in-zone activity

// Which sensor may turn the light on. Edit SOURCE:
//   "radar"  - only in-zone radar events (today's behaviour)
//   "pir"    - only PIR events
//   "either" - whichever fires first
const SOURCE = "radar";
const isPir = msg.topic === "rd03d/pir";
if (SOURCE === "radar" && isPir) return null;
if (SOURCE === "pir" && !isPir) return null;
return msg;

// One CSV line per trigger episode: which sensor fired first and the
// delay to the other, plus the radar position the PIR event carried and
// the one-way latency of the PIR event (needs SNTP on the node; t=0 means
// unsynced and latency is left blank). A lone episode (the other sensor never
// fired) is written, with the second-sensor and delay columns blank, when the
// next episode begins.
const GAP_MS = 60000;              // a new episode starts after this much quiet
const now = Date.now();
let ep = context.get("ep") || null;
const isPir = msg.topic === "rd03d/pir";
let d = {};
try { d = JSON.parse(msg.payload); } catch (e) { d = {}; }
if (!ep || now - ep.last > GAP_MS) {
    let pending = null;
    if (ep && ep.other === null) {
        pending = [new Date(ep.start).toISOString(), ep.first, "", "",
                   ep.pirRadar, ep.pirLatency].join(",");
    }
    ep = { start: now, first: isPir ? "pir" : "radar", other: null, last: now,
           pirRadar: "", pirLatency: "" };
    if (pending) node.send(Object.assign({}, msg, { payload: pending }));
}
ep.last = now;
const src = isPir ? "pir" : "radar";
if (isPir && ep.pirRadar === "") {
    ep.pirRadar = d.radar ? (d.radar.x + " " + d.radar.y) : "none";
    ep.pirLatency = d.t ? String(now - d.t) : "";
}
let line = null;
if (ep.other === null && src !== ep.first) {
    ep.other = src;
    line = [new Date(ep.start).toISOString(), ep.first, src, now - ep.start,
            ep.pirRadar, ep.pirLatency].join(",");
}
context.set("ep", ep);
if (!line) return null;
msg.payload = line;
return msg;
